import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M2.713 5.958a1 1 0 0 1 .574-1.916l10 3c.95.285.95 1.63 0 1.916l-10 3a1 1 0 0 1-.574-1.916L9.52 8z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["m12.838 10-9.154 3.051a1 1 0 0 0 .632 1.898l12-4c.912-.304.912-1.594 0-1.898l-12-4a1 1 0 0 0-.632 1.898z"] as readonly string[];

export const GreaterThanIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="greater-than" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
GreaterThanIcon.displayName = `Blueprint6.Icon.GreaterThanIcon`;

/**
 * @deprecated Use {@link GreaterThanIcon} instead.
 */
export const GreaterThan: typeof GreaterThanIcon = GreaterThanIcon;

export default GreaterThanIcon;
